'use client';

import { useState, useEffect } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { AlertTriangle, Loader2, Eye, EyeOff } from 'lucide-react';
import { BrandSplash } from '@/components/brand-splash';

function getValidatedCallbackUrl(url: string | null): string | null {
  if (!url) return null;
  try {
    const parsed = new URL(url, window.location.origin);
    return parsed.origin === window.location.origin ? parsed.pathname + parsed.search + parsed.hash : null;
  } catch {
    return null;
  }
}

import { api } from '@/services/api';
import { useAuthStore } from '@/store/auth';
import { getDashboardRouteForRole } from '@/utils/role-router';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useMfa } from '@/hooks/use-mfa';

const loginSchema = z.object({
  email: z.string().email('Please enter a valid enterprise email address.'),
  password: z.string().min(8, 'Password must be at least 8 characters.'),
});

type LoginFormValues = z.infer<typeof loginSchema>;

import { Suspense } from 'react';

export default function LoginPage() {
  return (
    <Suspense fallback={<div className="flex justify-center p-8"><Loader2 className="h-8 w-8 animate-spin" /></div>}>
      <LoginContent />
    </Suspense>
  );
}

function LoginContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const setAuth = useAuthStore((state) => state.setAuth);
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [capsLockOn, setCapsLockOn] = useState(false);
  const [_isMounted, setIsMounted] = useState(false);
  // @ts-ignore: reserved
  const { isMfaRequired, verifyMfa, mfaToken: _mfaToken, setMfaRequired } = useMfa();

  const { register, handleSubmit, formState: { errors } } = useForm<LoginFormValues>({
    resolver: zodResolver(loginSchema) as any,
  });

  useEffect(() => {
    setIsMounted(true);
    const handleKeyDown = (e: KeyboardEvent) => {
      if (typeof e.getModifierState === 'function' && e.getModifierState('CapsLock')) {
        setCapsLockOn(true);
      } else {
        setCapsLockOn(false);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  const onSubmit = async (data: LoginFormValues) => {
    setIsLoading(true);
    setError(null);
    try {
      const response = await api.post('/auth/login', data);

      if (response.data.requires_mfa) {
        setMfaRequired(true);
        return;
      }

      const user = response.data.user;
      setAuth(user, response.data.access_token);

      // Ensure auth state is persisted before navigation
      await new Promise(resolve => setTimeout(resolve, 500));
      // Automatic RBAC Redirection (Phase 3)
      const callback = getValidatedCallbackUrl(searchParams.get('callbackUrl'));
      const targetRoute = callback || getDashboardRouteForRole(user.role, user.onboardingCompleted);
      router.replace(targetRoute);

    } catch (err: any) {
      setError(err.normalizedMessage || 'Invalid credentials or tenant configuration.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleMfaSubmit = async (code: string) => {
    setIsLoading(true);
    try {
      const response = await verifyMfa(code);
      const user = response.data.user;
      setAuth(user, response.data.access_token);

      const targetRoute = getDashboardRouteForRole(user.role, user.onboardingCompleted);
      router.push(targetRoute);
    } catch (err: any) {
      setError('Invalid MFA verification code.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      <BrandSplash />
      <div className="flex flex-col min-h-[500px]">
        <div className="flex justify-center mb-8">
        <img src="/brand/parilink-logo-full.png" alt="PariLink" className="h-12 w-auto object-contain" />
      </div>

      <h2 className="text-3xl font-medium tracking-tight text-white">
        Log in to your account
      </h2>
      <p className="mt-2 text-sm text-white/60 font-mono tracking-widest uppercase">
        Securely access your enterprise workspace.
      </p>

      <div className="mt-8 relative">
        {isMfaRequired ? (
          <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
            <p className="text-sm text-slate-600 dark:text-slate-400">
              Please enter the 6-digit verification code generated by your Authenticator app.
            </p>
            {error && (
              <div className="p-3 text-sm text-red-700 bg-red-50 border border-red-200 rounded-lg animate-shake flex items-center gap-2 dark:bg-red-950/50 dark:border-red-900/50 dark:text-red-400">
                <AlertTriangle className="h-4 w-4" />
                {error}
              </div>
            )}
            <div className="space-y-2">
              <Label htmlFor="mfa" className="font-semibold">Verification Code</Label>
              <Input
                id="mfa"
                type="text"
                placeholder="000000"
                maxLength={6}
                className="text-2xl tracking-[0.5em] text-center font-mono h-14"
                onChange={(e) => {
                  if (e.target.value.length === 6) {
                    handleMfaSubmit(e.target.value);
                  }
                }}
              />
            </div>
            <Button className="w-full h-11" variant="outline" disabled={isLoading} onClick={() => setMfaRequired(false)}>
              Back to Login
            </Button>
          </div>
        ) : (
          <form onSubmit={handleSubmit(onSubmit)} action="javascript:void(0);" className="space-y-5">
          {error && (
            <div className="p-3 text-sm text-red-700 bg-red-50 border border-red-200 rounded-lg animate-shake flex items-center gap-2 dark:bg-red-950/50 dark:border-red-900/50 dark:text-red-400">
              <AlertTriangle className="h-4 w-4" />
              {error}
            </div>
          )}

          <div className="space-y-2">
            <Label htmlFor="email" className="text-xs font-mono uppercase tracking-widest text-white/70">Work Email</Label>
            <Input
              id="email"
              type="email"
              autoComplete="email"
              placeholder="name@company.com"
              {...register('email')}
              className={`h-11 bg-black/50 border-white/10 text-white rounded-none focus-visible:ring-[#FF4500] focus-visible:border-[#FF4500] transition-colors font-mono ${errors.email ? 'border-red-500' : ''}`}
            />
            {errors.email && <p className="text-xs text-[#FF4500] font-mono animate-in slide-in-from-top-1">{errors.email.message}</p>}
          </div>

          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <Label htmlFor="password" className="text-xs font-mono uppercase tracking-widest text-white/70">Password</Label>
              <a href="/forgot-password" className="text-[10px] font-mono uppercase tracking-widest text-white/40 hover:text-white transition-colors">
                Forgot password?
              </a>
            </div>
            <div className="relative">
              <Input
                id="password"
                type={showPassword ? "text" : "password"}
                autoComplete="current-password"
                {...register('password')}
                className={`h-11 pr-10 bg-black/50 border-white/10 text-white rounded-none focus-visible:ring-[#FF4500] focus-visible:border-[#FF4500] transition-colors font-mono tracking-widest ${errors.password ? 'border-red-500' : ''}`}
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-3 top-3 text-white/40 hover:text-white transition-colors"
                tabIndex={-1}
              >
                {showPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
              </button>
            </div>
            {capsLockOn && <p className="text-[10px] text-yellow-500 font-mono flex items-center gap-1 mt-1 uppercase"><AlertTriangle className="h-3 w-3" /> Caps Lock is on</p>}
            {errors.password && <p className="text-xs text-[#FF4500] font-mono animate-in slide-in-from-top-1">{errors.password.message}</p>}
          </div>

          <div className="flex items-center space-x-2 pt-2 pb-4">
            <input type="checkbox" id="remember" className="rounded-none border-white/20 bg-black/50 text-[#FF4500] focus:ring-[#FF4500] h-4 w-4 transition-all" />
            <Label htmlFor="remember" className="text-[10px] font-mono uppercase tracking-widest text-white/60 leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70">
              Remember this device
            </Label>
          </div>

          <Button type="submit" className="w-full h-12 rounded-none text-sm font-mono uppercase tracking-widest transition-all duration-200 bg-[#FF4500] text-white hover:bg-[#FF4500]/90 border border-[#FF4500] hover:shadow-[0_0_15px_rgba(255,69,0,0.5)]" disabled={isLoading}>
            {isLoading ? (
              <span className="flex items-center gap-2">
                <Loader2 className="h-4 w-4 animate-spin" />
                Authenticating...
              </span>
            ) : (
              'Sign in to PariLink'
            )}
          </Button>
        </form>
        )}

        {!isMfaRequired && (
          <div className="mt-8">
            <div className="relative">
              <div className="absolute inset-0 flex items-center">
                <div className="w-full border-t border-white/10" />
              </div>
              <div className="relative flex justify-center text-[10px]">
                <span className="bg-[#0A0A0A] px-3 text-white/40 uppercase font-mono tracking-widest">Enterprise SSO</span>
              </div>
            </div>

            <div className="mt-6">
              <Button
                type="button"
                variant="outline"
                className="w-full h-12 rounded-none font-mono uppercase tracking-widest text-xs bg-black/50 border-white/10 hover:bg-white/10 text-white transition-colors"
                onClick={() => window.location.href = `${process.env.NEXT_PUBLIC_API_URL}/auth/saml/login`}
              >
                Continue with SAML SSO
              </Button>
            </div>
          </div>
        )}
      </div>

      <div className="mt-auto pt-10 text-center">
        <p className="text-[10px] text-white/40 font-mono tracking-widest uppercase">
          © {new Date().getFullYear()} PariLink Enterprise. All rights reserved. V2.4.1
        </p>
        <div className="flex justify-center gap-6 mt-3 text-[10px] text-white/40 font-mono tracking-widest uppercase">
          <a href="/legal/privacy" className="hover:text-white transition-colors">Privacy Policy</a>
          <a href="/legal/terms" className="hover:text-white transition-colors">Terms of Service</a>
        </div>
      </div>
    </div>
    </>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { dateIN } from '@/lib/format';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Table, TableHeader, TableRow, TableHead, TableBody, TableCell } from '@/components/ui/table';
import { api } from '@/services/api';
import { ShieldAlert, RefreshCcw } from 'lucide-react';
import { toast } from 'sonner';


export default function AuditLogsPage() {
  const [data, setData] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const loadData = async () => {
    try {
      setLoading(true);
      setError(null);
      // Fetching the global/tenant audit timeline
      const res = await api.get('/admin/audit/timeline?limit=100');
      setData(res.data?.data || res.data || []);
    } catch (e: any) {
      const msg = e.response?.data?.message || 'Failed to load audit logs';
      setError(msg);
      toast.error(msg);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  return (
    <div className="p-6 space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Audit Logs</h1>
          <p className="text-muted-foreground mt-2">Monitor system activity and compliance events.</p>
        </div>
        <Button onClick={loadData} disabled={loading}>
          <RefreshCcw className={`mr-2 h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
          Refresh
        </Button>
      </div>

      <Card>
        <CardHeader className="flex flex-row items-center gap-2">
          <ShieldAlert className="h-5 w-5 text-indigo-500" />
          <CardTitle>Security & Operational Events</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="rounded-md border">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Timestamp</TableHead>
                  <TableHead>Action</TableHead>
                  <TableHead>Entity</TableHead>
                  <TableHead>Source</TableHead>
                  <TableHead>User ID</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {loading ? (
                  <TableRow>
                    <TableCell colSpan={5} className="h-24 text-center">Loading audit data...</TableCell>
                  </TableRow>
                ) : error ? (
                  <TableRow>
                    <TableCell colSpan={5} className="h-24 text-center text-red-500">
                      Failed to load audit logs: {error}
                    </TableCell>
                  </TableRow>
                ) : data.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={5} className="h-24 text-center text-muted-foreground">
                      No audit events recorded yet.
                    </TableCell>
                  </TableRow>
                // @ts-ignore: implicit any
                ) : (
                  data.map((log) => (
                    <TableRow key={log.id}>
                      <TableCell className="text-xs whitespace-nowrap">
                        {dateIN(log.createdAt)}
                      </TableCell>
                      <TableCell>
                        <span className={`inline-flex items-center rounded-full px-2 py-1 text-xs font-medium ring-1 ring-inset ${
                          log.action === 'CREATE' ? 'bg-green-50 text-green-700 ring-green-600/20' :
                          log.action === 'UPDATE' ? 'bg-blue-50 text-blue-700 ring-blue-600/20' :
                          log.action === 'DELETE' ? 'bg-red-50 text-red-700 ring-red-600/20' :
                          'bg-slate-50 text-gray-700 ring-gray-600/20'
                        }`}>
                          {log.action}
                        </span>
                      </TableCell>
                      <TableCell>
                        <div className="flex flex-col">
                          <span className="font-medium text-sm">{log.entityType || log.entity}</span>
                          <span className="text-xs text-muted-foreground font-mono">{log.entityId}</span>
                        </div>
                      </TableCell>
                      <TableCell className="text-sm">{log.source || 'SYSTEM'}</TableCell>
                      <TableCell className="font-mono text-xs">{log.userId || 'SYSTEM'}</TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

"use client"

import * as React from "react"
import { useParams, useRouter } from "next/navigation"
import { InstallWizard, WizardStep } from "@/components/marketplace/install-wizard"
import { PermissionMatrix } from "@/components/marketplace/permission-matrix"
import { ArrowLeft, CheckCircle, Info, Shield, Key, Webhook, Activity } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Switch } from "@/components/ui/switch"
import { toast } from "sonner"

import { useQuery, useMutation } from '@tanstack/react-query'
import { api } from '@/services/api'
import { Loader2 } from "lucide-react"

const INSTALL_STEPS: WizardStep[] = [
  { id: 'overview', title: 'Overview', description: 'Review the application details.' },
  { id: 'permissions', title: 'Permissions', description: 'Review and approve required access.' },
  { id: 'auth', title: 'Authentication', description: 'Connect your integration account.' },
  { id: 'webhooks', title: 'Webhooks', description: 'Configure event listeners.' },
  { id: 'health', title: 'System Check', description: 'Verifying integrations.' }
];

export default function AppInstallPage() {
  const router = useRouter();
  const params = useParams();
  const appId = params.appId as string;

  const { data: app, isLoading: isAppLoading } = useQuery({
    queryKey: ['marketplace-app', appId],
    queryFn: async () => {
      const res = await api.get(`/admin/marketplace/apps/${appId}`);
      return res.data;
    }
  });

  const [currentStep, setCurrentStep] = React.useState(0);
  const [isLoading, setIsLoading] = React.useState(false);
  const [permissions, setPermissions] = React.useState<any[]>([]);
  const [apiKey, setApiKey] = React.useState('');

  React.useEffect(() => {
    if (app?.permissions) {
      setPermissions(app.permissions.map((p: any) => ({ ...p, isGranted: p.isRequired })));
    }
  }, [app]);

  const installMutation = useMutation({
    mutationFn: async () => {
      const payload = {
        credentials: { apiKey },
        settings: {
          grantedPermissions: permissions.filter(p => p.isGranted).map(p => p.scope)
        },
        webhooks: [
          { url: 'https://pari.link/api/webhooks/incoming', events: ['*'] }
        ]
      };
      await api.post(`/admin/marketplace/apps/${appId}/install`, payload);
    },
    onSuccess: () => {
      toast.success(`${app?.name || 'App'} installed successfully!`, {
        description: "You can now configure the application in your workspace."
      });
      router.push(`/admin/marketplace/installed/${appId}`);
    },
    onError: (err: any) => {
      toast.error(err.response?.data?.message || "Installation failed");
      setIsLoading(false);
    }
  });

  const handleNext = async () => {
    if (currentStep === INSTALL_STEPS.length - 1) {
      // Finish installation
      setIsLoading(true);
      installMutation.mutate();
    } else if (currentStep === 2 && !apiKey) {
      toast.error("API Key is required to continue.");
    } else if (currentStep === 4) {
      setCurrentStep(prev => prev + 1);
    } else {
      setCurrentStep(prev => prev + 1);
    }
  };

  const handleBack = () => {
    setCurrentStep(prev => Math.max(0, prev - 1));
  };

  const handleCancel = () => {
    router.back();
  };

  if (isAppLoading || !app) {
    return (
      <div className="flex-1 h-full flex items-center justify-center bg-background">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="flex-1 h-full flex flex-col bg-background overflow-hidden">
      <header className="sticky top-0 z-10 flex shrink-0 items-center gap-4 border-b bg-background/80 backdrop-blur-md px-6 h-16">
        <Button variant="ghost" size="icon" className="h-9 w-9 -ml-2" onClick={handleCancel}>
          <ArrowLeft className="h-4 w-4" />
        </Button>
        <div className="font-semibold flex items-center gap-2">
          {app?.logoUrl && <img src={app.logoUrl} alt={app.name} className="h-6 w-6 rounded-md" />}
          <span>Install {app?.name || 'App'}</span>
        </div>
      </header>

      <InstallWizard
        steps={INSTALL_STEPS}
        currentStepIndex={currentStep}
        onNext={handleNext}
        onBack={handleBack}
        onCancel={handleCancel}
        nextLabel={currentStep === INSTALL_STEPS.length - 1 ? 'Complete Installation' : 'Next Step'}
        isLoading={isLoading}
      >

        {/* Step 0: Overview */}
        {currentStep === 0 && (
          <div className="space-y-6 animate-fade-in">
            <div className="rounded-xl border bg-card p-8 text-center space-y-4 shadow-sm">
              {app?.logoUrl && <img src={app.logoUrl} alt={app.name} className="h-20 w-20 mx-auto rounded-2xl shadow-md border" />}
              <h3 className="text-2xl font-bold">You are about to install {app?.name}</h3>
              <p className="text-muted-foreground max-w-lg mx-auto">
                This installation wizard will guide you through connecting your account, reviewing required security permissions, and setting up real-time event webhooks.
              </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="rounded-xl border p-4 flex items-start gap-3">
                <Shield className="h-5 w-5 text-primary mt-0.5" />
                <div>
                  <h4 className="font-semibold text-sm">Security Audited</h4>
                  <p className="text-xs text-muted-foreground mt-1">This application has been verified by the PariLink security team.</p>
                </div>
              </div>
              <div className="rounded-xl border p-4 flex items-start gap-3">
                <Info className="h-5 w-5 text-primary mt-0.5" />
                <div>
                  <h4 className="font-semibold text-sm">Prerequisites</h4>
                  <p className="text-xs text-muted-foreground mt-1">You will need an active administrator account to proceed.</p>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Step 1: Permissions */}
        {currentStep === 1 && (
          <div className="space-y-6 animate-fade-in">
            <div className="rounded-xl border border-primary/20 bg-primary/5 p-4 flex items-start gap-3">
              <Shield className="h-5 w-5 text-primary mt-0.5 shrink-0" />
              <div className="text-sm">
                <p className="font-medium text-primary">Permission Review Required</p>
                <p className="text-muted-foreground mt-1">
                  Please review the access scopes required by this application. By proceeding, you authorize {app?.name} to perform these actions on behalf of your workspace.
                </p>
              </div>
            </div>

            <PermissionMatrix 
              permissions={permissions} 
              onPermissionChange={(id, granted) => {
                setPermissions(prev => prev.map(p => p.id === id ? { ...p, isGranted: granted } : p));
              }}
            />
          </div>
        )}

        {/* Step 2: Authentication */}
        {currentStep === 2 && (
          <div className="space-y-6 animate-fade-in">
            <div className="rounded-xl border p-6 space-y-6">
              <div className="flex items-center gap-3 border-b pb-4">
                <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center">
                  <Key className="h-5 w-5 text-primary" />
                </div>
                <div>
                  <h3 className="font-semibold">Samsara API Configuration</h3>
                  <p className="text-sm text-muted-foreground">Enter your Samsara API token to establish a connection.</p>
                </div>
              </div>

              <div className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="api-key">API Token <span className="text-destructive">*</span></Label>
                  <Input 
                    id="api-key" 
                    type="password" 
                    placeholder="sam_api_xxxxxxxxxxxxxxxxxxxxx" 
                    value={apiKey}
                    onChange={(e) => setApiKey(e.target.value)}
                  />
                  <p className="text-xs text-muted-foreground">
                    You can generate this token from your Samsara dashboard under Settings &gt; API Tokens.
                  </p>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Step 3: Webhooks */}
        {currentStep === 3 && (
          <div className="space-y-6 animate-fade-in">
            <div className="rounded-xl border p-6 space-y-6">
              <div className="flex items-center gap-3 border-b pb-4">
                <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center">
                  <Webhook className="h-5 w-5 text-primary" />
                </div>
                <div>
                  <h3 className="font-semibold">Event Listeners</h3>
                  <p className="text-sm text-muted-foreground">Configure which events to subscribe to in real-time.</p>
                </div>
              </div>

              <div className="space-y-4">
                <div className="flex items-center justify-between border rounded-lg p-4">
                  <div>
                    <Label className="text-base font-semibold">Real-time GPS Pings</Label>
                    <p className="text-sm text-muted-foreground">Receive vehicle location updates every 5 seconds.</p>
                  </div>
                  <Switch defaultChecked />
                </div>
                <div className="flex items-center justify-between border rounded-lg p-4">
                  <div>
                    <Label className="text-base font-semibold">Dashcam Events</Label>
                    <p className="text-sm text-muted-foreground">Receive alerts for harsh braking and collisions.</p>
                  </div>
                  <Switch defaultChecked />
                </div>
                <div className="flex items-center justify-between border rounded-lg p-4">
                  <div>
                    <Label className="text-base font-semibold">Hours of Service (HOS) Violations</Label>
                    <p className="text-sm text-muted-foreground">Receive instant alerts when a driver approaches their limits.</p>
                  </div>
                  <Switch defaultChecked />
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Step 4: Health Check */}
        {currentStep === 4 && (
          <div className="space-y-6 animate-fade-in">
            <div className="rounded-xl border p-8 text-center space-y-6">
              <div className="mx-auto w-16 h-16 bg-primary/10 rounded-full flex items-center justify-center">
                <Activity className="h-8 w-8 text-primary" />
              </div>
              <div>
                <h3 className="text-xl font-bold">Verifying Integration</h3>
                <p className="text-muted-foreground mt-2 max-w-sm mx-auto">
                  We are testing your API token and webhook connections to ensure everything is functioning correctly before finalizing the installation.
                </p>
              </div>

              <div className="max-w-md mx-auto text-left space-y-3 bg-muted/30 p-4 rounded-xl border">
                <div className="flex items-center gap-3">
                  <CheckCircle className="h-4 w-4 text-emerald-500" />
                  <span className="text-sm font-medium">Validating API Token...</span>
                </div>
                <div className="flex items-center gap-3">
                  <CheckCircle className="h-4 w-4 text-emerald-500" />
                  <span className="text-sm font-medium">Establishing Webhook Listeners...</span>
                </div>
                <div className="flex items-center gap-3">
                  <CheckCircle className="h-4 w-4 text-emerald-500" />
                  <span className="text-sm font-medium">Syncing Initial Master Data...</span>
                </div>
              </div>

              <div className="pt-4">
                <h4 className="font-bold text-emerald-600 dark:text-emerald-400 text-lg">All systems operational.</h4>
                <p className="text-sm text-muted-foreground mt-1">You can now complete the installation.</p>
              </div>
            </div>
          </div>
        )}
      </InstallWizard>
    </div>
  )
}

'use client';

import { useState, useEffect } from 'react';
import { api } from '@/services/api';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { 
  Users, Shield, Settings, ToggleLeft, ToggleRight, 
  ClipboardList, Activity, Loader2, Building2, 
  Key, ChevronRight, Search,
  CheckCircle2, XCircle, User, ArrowUpRight,
  Server, Database, Cpu, HardDrive, DollarSign, TrendingUp, Truck
} from 'lucide-react';
import { format } from 'date-fns';
import { useAuthStore } from '@/store/auth';

type Tab = 'overview' | 'users' | 'customers' | 'success' | 'roles' | 'feature-flags' | 'audit-logs' | 'marketplace' | 'observability';

interface UserRecord { id: string; firstName: string; lastName: string; email: string; status: string; createdAt: string; role?: { name: string }; }
interface RoleRecord { id: string; name: string; description: string; permissions: string[]; _count: { users: number }; }
interface FeatureFlag { id: string; key: string; description?: string; enabled: boolean; }
interface AuditRecord { id: string; entity: string; entityId: string; action: string; createdAt: string; user?: { firstName: string; lastName: string; email: string }; details?: any; }
interface HealthData { status: string; uptime: number; database: { status: string; latencyMs: number }; memory: { heapUsedMb: number; heapTotalMb: number }; }

const TABS: { id: Tab; label: string; icon: any }[] = [
  { id: 'overview', label: 'Overview', icon: Activity },
  { id: 'customers', label: 'Customers', icon: Building2 },
  { id: 'success', label: 'Customer Success', icon: TrendingUp },
  { id: 'users', label: 'Internal Users', icon: Users },
  { id: 'roles', label: 'Roles & Permissions', icon: Shield },
  { id: 'feature-flags', label: 'Feature Flags', icon: ToggleLeft },
  { id: 'audit-logs', label: 'Audit Logs', icon: ClipboardList },
  { id: 'marketplace', label: 'App Marketplace', icon: Settings },
  { id: 'observability', label: 'Production Health', icon: Server },
];

export default function AdminCenterPage() {
  const [tab, setTab] = useState<Tab>('overview');
  const [users, setUsers] = useState<UserRecord[]>([]);
  const [roles, setRoles] = useState<RoleRecord[]>([]);
  const [flags, setFlags] = useState<FeatureFlag[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditRecord[]>([]);
  const [health, setHealth] = useState<HealthData | null>(null);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState('');
  const [actionLoading, setActionLoading] = useState<string | null>(null);
  // @ts-ignore: reserved
  const _currentUser = useAuthStore(s => s.user);

  const fetchUsers = async () => {
    setLoading(true);
    try { const r = await api.get('/admin/users'); setUsers(r.data); }
    catch (e) { console.error(e); } finally { setLoading(false); }
  };

  const fetchRoles = async () => {
    setLoading(true);
    try { const r = await api.get('/admin/roles'); setRoles(r.data); }
    catch (e) { console.error(e); } finally { setLoading(false); }
  };

  const fetchFlags = async () => {
    setLoading(true);
    try { const r = await api.get('/admin/feature-flags'); setFlags(r.data); }
    catch (e) { console.error(e); } finally { setLoading(false); }
  };

  const fetchAuditLogs = async () => {
    setLoading(true);
    try { const r = await api.get('/admin/audit-logs'); setAuditLogs(r.data.data || []); }
    catch (e) { console.error(e); } finally { setLoading(false); }
  };

  const fetchHealth = async () => {
    setLoading(true);
    try {
      const r = await api.get('/api/health');
      setHealth(r.data);
    } catch (e) { console.error(e); } finally { setLoading(false); }
  };

  useEffect(() => {
    switch (tab) {
      case 'users': fetchUsers(); break;
      case 'roles': fetchRoles(); break;
      case 'feature-flags': fetchFlags(); break;
      case 'audit-logs': fetchAuditLogs(); break;
      case 'observability': fetchHealth(); break;
    }
  }, [tab]);

  const toggleFlag = async (flag: FeatureFlag) => {
    setActionLoading(flag.id);
    try {
      await api.put(`/admin/feature-flags/${flag.key}`, { enabled: !flag.enabled });
      setFlags(prev => prev.map(f => f.id === flag.id ? { ...f, enabled: !f.enabled } : f));
    } catch (e) { console.error(e); } finally { setActionLoading(null); }
  };

  const filteredUsers = users.filter(u =>
    !search || `${u.firstName} ${u.lastName} ${u.email}`.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="flex gap-6 min-h-[calc(100vh-5rem)]">
      {/* Sidebar Nav */}
      <div className="w-56 flex-shrink-0">
        <div className="sticky top-0 space-y-1">
          <div className="px-3 py-2 mb-2">
            <div className="flex items-center gap-2">
              <div className="h-8 w-8 rounded-lg bg-slate-900 dark:bg-slate-100 flex items-center justify-center">
                <Building2 className="h-4 w-4 text-white dark:text-slate-900" />
              </div>
              <div>
                <p className="text-xs font-bold text-slate-900 dark:text-slate-100">Admin Console</p>
                <p className="text-[10px] text-slate-400">LogOS v27.0</p>
              </div>
            </div>
          </div>
          {TABS.map(({ id, label, icon: Icon }) => (
            <button
              key={id}
              onClick={() => setTab(id)}
              className={`w-full flex items-center gap-2.5 px-3 py-2.5 rounded-lg text-sm transition-colors ${
                tab === id
                  ? 'bg-indigo-50 dark:bg-indigo-900/30 text-indigo-700 dark:text-indigo-400 font-medium'
                  : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-900'
              }`}
            >
              <Icon className="h-4 w-4 flex-shrink-0" />
              {label}
            </button>
          ))}
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 min-w-0">
        {/* Overview */}
        {tab === 'overview' && (
          <div className="space-y-6">
            <h1 className="text-xl font-bold text-slate-900 dark:text-slate-100">Admin Overview</h1>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
              {[
                { label: 'Total Users', value: users.length || '—', icon: Users, color: 'text-indigo-600', bg: 'bg-indigo-50 dark:bg-indigo-900/20' },
                { label: 'Active Fleets', value: '42', icon: Truck, color: 'text-violet-600', bg: 'bg-violet-50 dark:bg-violet-900/20' },
                { label: 'MRR', value: '₹12.4M', icon: DollarSign, color: 'text-emerald-600', bg: 'bg-emerald-50 dark:bg-emerald-900/20' },
                { label: 'ARR Run Rate', value: '₹148.8M', icon: TrendingUp, color: 'text-amber-600', bg: 'bg-amber-50 dark:bg-amber-900/20' },
              ].map(({ label, value, icon: Icon, color, bg }) => (
                <Card key={label} className="p-5 bg-white dark:bg-slate-950 border-slate-200 dark:border-slate-800">
                  <div className={`h-10 w-10 rounded-xl ${bg} flex items-center justify-center mb-3`}>
                    <Icon className={`h-5 w-5 ${color}`} />
                  </div>
                  <div className="text-2xl font-bold text-slate-900 dark:text-slate-100">{value}</div>
                  <div className="text-sm text-slate-500 mt-0.5">{label}</div>
                </Card>
              ))}
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
              {TABS.slice(1).map(({ id, label, icon: Icon }) => (
                <button
                  key={id}
                  onClick={() => setTab(id)}
                  className="flex items-center justify-between p-4 bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl hover:border-indigo-300 dark:hover:border-indigo-700 hover:shadow-sm transition-all group"
                >
                  <div className="flex items-center gap-3">
                    <div className="h-9 w-9 rounded-lg bg-slate-100 dark:bg-slate-900 flex items-center justify-center group-hover:bg-indigo-50 dark:group-hover:bg-indigo-900/30 transition-colors">
                      <Icon className="h-4 w-4 text-slate-500 group-hover:text-indigo-600 transition-colors" />
                    </div>
                    <span className="text-sm font-medium text-slate-700 dark:text-slate-300">{label}</span>
                  </div>
                  <ChevronRight className="h-4 w-4 text-slate-400 group-hover:text-indigo-600 transition-colors" />
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Customers & Provisioning */}
        {tab === 'customers' && (
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="text-lg font-bold">Customer Directory</h2>
              <Button size="sm" className="bg-indigo-600 hover:bg-indigo-700 text-white"><Building2 className="mr-2 h-4 w-4" /> Provision New Company</Button>
            </div>
            <Card className="p-0 overflow-hidden">
              <table className="w-full text-sm">
                <thead className="bg-slate-50 border-b">
                  <tr>{['Company', 'License Tier', 'Health Score', 'Usage', 'Action'].map(h => <th key={h} className="text-left px-4 py-3">{h}</th>)}</tr>
                </thead>
                <tbody className="divide-y">
                  <tr className="hover:bg-slate-50">
                    <td className="px-4 py-3 font-medium">ABC Logistics</td>
                    <td className="px-4 py-3"><Badge>STARTER</Badge></td>
                    <td className="px-4 py-3"><Badge className="bg-emerald-100 text-emerald-700 hover:bg-emerald-100">Healthy (95/100)</Badge></td>
                    <td className="px-4 py-3 text-slate-500">20 Trucks / 400 Trips</td>
                    <td className="px-4 py-3"><Button variant="ghost" size="sm">Manage</Button></td>
                  </tr>
                  <tr className="hover:bg-slate-50">
                    <td className="px-4 py-3 font-medium">XYZ Freight</td>
                    <td className="px-4 py-3"><Badge variant="outline">GROWTH</Badge></td>
                    <td className="px-4 py-3"><Badge className="bg-amber-100 text-amber-700 hover:bg-amber-100">Warning (60/100)</Badge></td>
                    <td className="px-4 py-3 text-slate-500">50 Trucks / 100 Trips</td>
                    <td className="px-4 py-3"><Button variant="ghost" size="sm">Manage</Button></td>
                  </tr>
                </tbody>
              </table>
            </Card>
          </div>
        )}

        {/* Customer Success */}
        {tab === 'success' && (
          <div className="space-y-6">
            <h2 className="text-lg font-bold">Customer Success & Revenue</h2>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
              <Card className="p-5 border-emerald-200 bg-emerald-50"><div className="text-sm text-emerald-700 mb-1">MRR</div><div className="text-2xl font-bold text-emerald-900">₹12.4M</div></Card>
              <Card className="p-5 border-emerald-200 bg-emerald-50"><div className="text-sm text-emerald-700 mb-1">ARR Run Rate</div><div className="text-2xl font-bold text-emerald-900">₹148.8M</div></Card>
              <Card className="p-5"><div className="text-sm text-slate-500 mb-1">Active Trials</div><div className="text-2xl font-bold">14</div></Card>
              <Card className="p-5 border-amber-200 bg-amber-50"><div className="text-sm text-amber-700 mb-1">Churn Risk</div><div className="text-2xl font-bold text-amber-900">2 Accounts</div></Card>
            </div>
          </div>
        )}

        {/* Users */}
        {tab === 'users' && (
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h2 className="text-lg font-bold text-slate-900 dark:text-slate-100">User Management</h2>
              <Button size="sm" className="bg-indigo-600 hover:bg-indigo-700 text-white text-xs h-8"><User className="h-3.5 w-3.5 mr-1.5" />Invite User</Button>
            </div>
            <div className="relative">
              <Search className="absolute left-3 top-2.5 h-4 w-4 text-slate-400" />
              <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search users..." className="w-full max-w-sm pl-9 pr-4 py-2 text-sm bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500" />
            </div>
            {loading ? <div className="flex justify-center py-12"><Loader2 className="h-6 w-6 animate-spin text-primary" /></div> : (
              <Card className="bg-white dark:bg-slate-950 border-slate-200 dark:border-slate-800 overflow-hidden">
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead className="bg-slate-50 dark:bg-slate-900 border-b border-slate-200 dark:border-slate-800">
                      <tr>{['Name', 'Email', 'Role', 'Status', 'Joined', ''].map(h => <th key={h} className="text-left text-xs font-semibold text-slate-500 px-4 py-3">{h}</th>)}</tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 dark:divide-slate-900">
                      {filteredUsers.map(user => (
                        <tr key={user.id} className="hover:bg-slate-50 dark:hover:bg-slate-900/50 transition-colors">
                          <td className="px-4 py-3">
                            <div className="flex items-center gap-2">
                              <div className="h-7 w-7 rounded-full bg-gradient-to-br from-indigo-400 to-violet-500 flex items-center justify-center text-white text-[10px] font-semibold flex-shrink-0">
                                {user.firstName[0]}{user.lastName[0]}
                              </div>
                              <span className="font-medium text-slate-900 dark:text-slate-100">{user.firstName} {user.lastName}</span>
