              type="text"
              placeholder="Search roles…"
              value={search}
              onChange={e => setSearch(e.target.value)}
              className="h-9 w-full rounded-lg border border-input bg-background pl-9 pr-3 text-sm focus:outline-none focus:ring-2 focus:ring-ring"
            />
          </div>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto px-6 py-5">
          {isLoading ? (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
              {Array.from({ length: 6 }).map((_, i) => (
                <div key={i} className="rounded-xl border border-border bg-card p-5 animate-in fade-in duration-120 opacity-50">
                  <div className="flex items-start gap-3">
                    <div className="h-9 w-9 rounded-xl bg-muted shrink-0" />
                    <div className="space-y-2.5 w-full">
                      <div className="h-5 bg-muted rounded w-1/3" />
                      <div className="h-3 bg-muted rounded w-2/3" />
                      <div className="flex gap-3 mt-1.5 pt-0.5">
                        <div className="h-3 bg-muted rounded w-16" />
                        <div className="h-3 bg-muted rounded w-20" />
                        <div className="h-3 bg-muted rounded w-24" />
                      </div>
                    </div>
                  </div>
                  <div className="mt-3 pt-3 border-t border-border/60">
                    <div className="flex gap-1.5">
                      <div className="h-5 bg-muted rounded w-16" />
                      <div className="h-5 bg-muted rounded w-20" />
                      <div className="h-5 bg-muted rounded w-14" />
                    </div>
                  </div>
                </div>
              ))}
            </div>
          ) : roles.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-20 text-center">
              <div className="h-14 w-14 rounded-full bg-muted flex items-center justify-center mb-4">
                <Shield className="h-6 w-6 text-muted-foreground" />
              </div>
              <h3 className="font-semibold text-foreground mb-1">
                {search ? `No roles matching "${search}"` : 'No roles yet'}
              </h3>
              <p className="text-sm text-muted-foreground mb-4">
                {search ? 'Try a different search term' : 'Create your first role to control user access'}
              </p>
              {!search && (
                <Button onClick={openCreate} className="gap-2">
                  <Plus className="h-4 w-4" />
                  Create Role
                </Button>
              )}
            </div>
          ) : (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
              {roles.map(role => (
                <RoleCard
                  key={role.id}
                  role={role}
                  onEdit={() => openEdit(role)}
                  onDelete={() => handleDelete(role)}
                />
              ))}
            </div>
          )}
        </div>
      </div>
    </RoleGuard>
  );
}

