// Seeded route pins for demo
const DEMO_ROUTES = [
  { from: 'Ahmedabad', to: 'Mumbai', status: 'IN_TRANSIT' as const },
  { from: 'Delhi', to: 'Ahmedabad', status: 'IN_TRANSIT' as const },
